            new Quote { Id = "https://hi.wikiquote.org/wiki/हजारीप्रसाद_द्विवेदी", Text = "वह साहित्य समाज का उद्धार कर सकता है, जो केवल बुद्धि को नहीं, हृदय को भी आकर्षित करे।", Author = "हजारी प्रसाद द्विवेदी" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हजारीप्रसाद_द्विवेदी", Text = "सभ्यता का विकास हमेशा ही जटिलता की ओर रहा है।", Author = "हजारी प्रसाद द्विवेदी" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हजारीप्रसाद_द्विवेदी", Text = "जिस साहित्य की कोई आलोचना नहीं, वह निश्चय ही उपेक्षणीय है।", Author = "हजारी प्रसाद द्विवेदी" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हजारीप्रसाद_द्विवेदी", Text = "ईमानदारी से कहा जाए तो, किसी भी युग का साहित्य उस युग के लोगों के लिए ही होता है।", Author = "हजारी प्रसाद द्विवेदी" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हजारीप्रसाद_द्विवेदी", Text = "जब हम अतीत को समझते हैं, तभी वर्तमान को जी सकते हैं।", Author = "हजारी प्रसाद द्विवेदी" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हजारीप्रसाद_द्विवेदी", Text = "साहित्य वह आइना है जिसमें समाज अपना प्रतिबिंब देख सकता है।", Author = "हजारी प्रसाद द्विवेदी" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हजारीप्रसाद_द्विवेदी", Text = "कला वही है जो जीवन को समृद्ध करे, उसे नीरस न बनाए।", Author = "हजारी प्रसाद द्विवेदी" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हजारीप्रसाद_द्विवेदी", Text = "सच्ची मानवता का बोध ही महान साहित्य का मूल है।", Author = "हजारी प्रसाद द्विवेदी" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हजारीप्रसाद_द्विवेदी", Text = "जो बातें हमें सहज लगती हैं, वे ही अक्सर अधिक गहरी होती हैं।", Author = "हजारी प्रसाद द्विवेदी" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हजारीप्रसाद_द्विवेदी", Text = "ईमानदारी से कहें तो, हमें न तो अतीत को भूलना चाहिए और न ही उसे वर्तमान पर हावी होने देना चाहिए।", Author = "हजारी प्रसाद द्विवेदी" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हजारीप्रसाद_द्विवेदी", Text = "साहित्यकार का धर्म है कि वह समाज की विसंगतियों को उजागर करे, पर निराश न करे।", Author = "हजारी प्रसाद द्विवेदी" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हजारीप्रसाद_द्विवेदी", Text = "अपने मन की बात कहने का साहस ही सबसे बड़ी कला है।", Author = "हजारी प्रसाद द्विवेदी" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हजारीप्रसाद_द्विवेदी", Text = "जो संस्कृति जीवन से विमुख हो जाती है, वह मर जाती है।", Author = "हजारी प्रसाद द्विवेदी" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हजारीप्रसाद_द्विवेदी", Text = "शब्दों में इतनी शक्ति होती है कि वे संसार को बदल सकते हैं।", Author = "हजारी प्रसाद द्विवेदी" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हजारीप्रसाद_द्विवेदी", Text = "सभ्य वही है जो दूसरे के मन को समझ सके।", Author = "हजारी प्रसाद द्विवेदी" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हजारीप्रसाद_द्विवेदी", Text = "इतिहास केवल तथ्यों का लेखा-जोखा नहीं, बल्कि अनुभवों का एक प्रवाह है।", Author = "हजारी प्रसाद द्विवेदी" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हजारीप्रसाद_द्विवेदी", Text = "साहित्यिक मूल्य वही है जो व्यक्ति को अधिक मनुष्य बनाए।", Author = "हजारी प्रसाद द्विवेदी" },
